-- Task 22: bilingual exhibition labels for the frozen Third Volume (30 records).
-- Visible features are separated from collector naming and scientific/authentication conclusions.

CREATE TEMP TABLE v3_labels(
  catalog_code TEXT,
  zh_label TEXT,
  zh_text TEXT,
  eo_label TEXT,
  eo_text TEXT
) ON COMMIT DROP;


SELECT a.id,'zh',l.zh_label,l.zh_text,'published','v3-v0.1'
FROM v3_labels l JOIN cultural_assets a ON a.catalog_code=l.catalog_code
ON CONFLICT(asset_id,locale,version) DO NOTHING;

SELECT a.id,'eo',l.eo_label,l.eo_text,'published','v3-v0.1'
FROM v3_labels l JOIN cultural_assets a ON a.catalog_code=l.catalog_code
ON CONFLICT(asset_id,locale,version) DO NOTHING;
